head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF05301.xml";
scwin.vScrenTpCD = "";
scwin.vBzProcsNo;
scwin.TR_JOB;
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.rowPos;
scwin.mktTpCd;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; //거래시장구분 1= 유가, 2=코스닥


scwin.fn_searchCode = function() {
    /*
    02207-추적기초자산국내외구분코드
    */
    var arrCid = [{
        cid: "TRACE_ULY_DOMFORN_TP_CD",
        cnm: "cmb_TRACE_ULY_DOMFORN_TP_CD"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT" + "&CD_ID_M='TRACE_ULY_DOMFORN_TP_CD'";
    dts_Cod.DataID = encodeURI(url);
    dts_Cod.reset();
    var strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        //alert('[objCod]'+objCod);
        if (objCod == null) {
            $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getTotalRow(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") == arrCid[i].cid) {
                strCbd = strCbd + (strCbd == "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};
scwin.fn_initForm = function(initTyp) {
    if (initTyp == "C") {
        img_ISU_NM.src = "../img/btn_search.gif";
        img_ISU_NM.setDisabled(false);
    } else if (initTyp == "X") {
        img_ISU_NM.src = "../img/btn_search_d.gif";
        img_ISU_NM.setDisabled(true);
    }
};
scwin.fn_GetPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_ISU_CD); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = $c.stf.getObjectValue(cmb_SECUGRP_ID);
    arrPar[3] = scwin.mktTpCd;
    arrPar[4] = SEARCH_TYP_SEC;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_NM);
        txb_ISU_ENG_NM.setValue(arrPar[0].ISU_ENG_NM);
        dts_Item.setCellData(1, 'ISUR_CD', arrPar[0].ISUR_CD);
    }
};
scwin.fn_read_sync = function() {
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    var url = "/Prelisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=readBenfcertPrelisting&inputMessageId=BENFCERT_PREEXAM_INOUT" + "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    dts_Item.DataID = encodeURI(url);
    dts_Item.Reset();
    scwin.fn_changeForm(dts_Item.getCellData(1, "INVSTG_PROG_STAT_CD"));
    if (js_dep_cd == '2520' || //유가증권시장본부 - 상장부 - 상장심사팀
        js_dep_cd == '2540' ||
        js_dep_cd == '2B20' || // 유가증권시장본부 - 증권상품시장부 - ETF시장팀
        js_dep_cd == '2615') // 유가증권시장본부 - 상장부 - 기업심사팀(2615) by nhkw

    {
        //심사1팀,심사2팀,상품상장팀
        buttonSet.setUpdateStatus();
    } else {
        buttonSet.setErrorStatus(); //disable 시킨다.

    }
};
scwin.strCbd_INVSTG_PROG_STAT_CD_1 = "02^심사완료,05^심사철회";
scwin.strCbd_INVSTG_PROG_STAT_CD_2 = "02^심사완료,30^상장,05^심사철회";
scwin.fn_changeForm = function(gStatCd) {
    //alert("[gStatCd]:"+gStatCd);
    //alert("[gStatCd.charAt(0) ]:"+gStatCd.charAt(0) );
    if (gStatCd != "" && gStatCd.charAt(0) != '0') {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(true);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_2;
    } else {
        cmb_INVSTG_PROG_STAT_CD.setDisabled(false);
        cmb_INVSTG_PROG_STAT_CD.CBData = scwin.strCbd_INVSTG_PROG_STAT_CD_1;
    }
    cmb_INVSTG_PROG_STAT_CD.BindColVal = gStatCd;
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        $c.win.alert("[종목]을 선택하세요.");
        img_ISU_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_NM) == "") {
        $c.win.alert("[한글종목명]를 입력하세요.");
        txb_ISU_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_ENG_NM) == "") {
        $c.win.alert("[영문종목명]를 입력하세요.");
        txb_ISU_ENG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_INVSTG_BILL_ACPT_DD) == "") {
        $c.win.alert("[청구서접수일자]를 입력하세요.");
        edt_INVSTG_BILL_ACPT_DD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "") {
        $c.win.alert("[유가증권]을 선택하세요..");
        cmb_SECUGRP_ID.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_SECUGRP_ID) == "EF" || $c.stf.getObjectValue(cmb_SECUGRP_ID) == "FE") {
        if ($c.stf.getObjectValue(cmb_ETF_TP_CD) == "") {
            $c.win.alert("[ETF분류]를 선택하세요..");
            cmb_ETF_TP_CD.focus();
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_INVSTG_PROG_STAT_CD) == "") {
        $c.win.alert("[심사상태]를 입력하세요.");
        cmb_INVSTG_PROG_STAT_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_TRACE_ULY_DOMFORN_TP_CD) == "") {
        $c.win.alert("[추적기초자산국내외구분]을 선택하세요..");
        cmb_TRACE_ULY_DOMFORN_TP_CD.focus();
        return false;
    }
    if ($c.stf.getObjectValue(edt_DECL_SPD) == "") {
        $c.win.alert("[신고스프레드]를 입력하세요..");
        edt_DECL_SPD.focus();
        return false;
    }
    /*
    if (getObjectValue(edt_EXST_STRT_DD) == "") {
    	alert("[존립개시일]을 입력하세요.");edt_EXST_STRT_DD.focus();return false;
    }
    if (getObjectValue(edt_EXST_END_DD) == "") {
    	alert("[존립종료일]을 입력하세요.");edt_EXST_END_DD.focus();return false;
    }
    */
    if ($c.stf.getObjectValue(edt_EXST_STRT_DD) != "") {
        if (parseInt(edt_EXST_STRT_DD.getValue(), 10) >= parseInt(edt_EXST_END_DD.getValue(), 10)) {
            $c.win.alert("[존립개시일]은 [존립종료일]보다 작아야 합니다. 다시 입력해주세요");
            return false;
        }
    }
    if ($c.stf.getObjectValue(txb_TRST_CALC_PD_CONTN) == "") {
        $c.win.alert("[회계기간]을 입력하세요.");
        txb_TRST_CALC_PD_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_NM) == "") {
        $c.win.alert("[신청회사담당자명]을 입력하세요.");
        txb_APPL_COM_CHRG_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_APPL_COM_CHRG_TEL_NO) == "") {
        $c.win.alert("[신청회사담당자연락처]를 입력하세요.");
        txb_APPL_COM_CHRG_TEL_NO.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_INSERT;*/
            X = TB_JOB_INSERT;
            dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            //alert("BZ_PROCS_NO>>>>>>>> :"+dts_Item.NameValue(1,"BZ_PROCS_NO"));

            scwin.fn_trs();
        }
    }
};
scwin.fn_update = function() {
    scwin.TR_JOB = 'U';
    if (scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return; /*ORG SRC: dts_Item.UserStatus(1) = TB_JOB_UPDATE;*/ X = TB_JOB_UPDATE;
        scwin.fn_trs();
    }
};
scwin.fn_trs = function() {
    if (scwin.TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    }
    //alert("BZ_PROCS_NO <<<<<:"+dts_Item.NameValue(1,"BZ_PROCS_NO"));
    dts_Item.setCellData(1, "EXAMPRN_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "FST_EXAMPRN_EMP_NO", js_emp_no);
    trs_Save.Action = "/Prelisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=saveBenfcertPrelisting&inputMessageId=BENFCERT_PREEXAM_INOUT";
    trs_Save.KeyName = "toinb_dataid4";
    trs_Save.KeyValue = "JSP(I:pInput=dts_Item)";
    trs_Save.Post();
};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_list_sync;
    fr_fn_list_sync();
};


/********************************************** 
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 * 현업요청으로 기능삭제
 ***********************************************/
scwin.fn_print = function() {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();
    //dts_Print.NameValue(1, "TEST") = dtsObj.NameValue(1, "COM_NM");

    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print);
    //alert('[testDateSet]'+testDateSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    var rex_rptname = "RLDSTF00003";
    var userParam = [{
        uid: "HEADER",
        unm: "ETF"
    }, {
        uid: "ISU_NM",
        unm: dts_Item.getCellData(1, "ISU_NM")
    }, {
        uid: "INVSTG_BILL_ACPT_DD",
        unm: dts_Item.getCellData(1, "INVSTG_BILL_ACPT_DD")
    }, {
        uid: "FST_EXAMPRN_EMP_NM",
        unm: dts_Item.getCellData(1, "FST_EXAMPRN_EMP_NM")
    }, {
        uid: "LIST_DD",
        unm: dts_Item.getCellData(1, "LIST_DD")
    }, {
        uid: "LIST_LM_CD",
        unm: $c.stf.fn_getComboTextValue(cmb_INVSTG_PROG_STAT_CD)
    }, {
        uid: "PER1STK_AMT",
        unm: dts_Item.getCellData(1, "PARVAL")
    }, {
        uid: "LIST_STKCNT",
        unm: dts_Item.getCellData(1, "LIST_STKCNT")
    }, {
        uid: "APPL_COM_CHRG_NM",
        unm: dts_Item.getCellData(1, "APPL_COM_CHRG_NM")
    }, {
        uid: "APPL_COM_CHRG_TEL_NO",
        unm: dts_Item.getCellData(1, "APPL_COM_CHRG_TEL_NO")
    }, {
        uid: "TRST_CALC_PD_CONTN",
        unm: dts_Item.getCellData(1, "TRST_CALC_PD_CONTN")
    }, {
        uid: "EXST_TERM_DD",
        unm: dts_Item.getCellData(1, "EXST_STRT_DD") + dts_Item.getCellData(1, "EXST_END_DD")
    }, {
        uid: "TRST_TOTAMT",
        unm: dts_Item.getCellData(1, "TRST_TOTAMT")
    }];

    //Rexpert 미리보기 호출 
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};
scwin.img_ISU_NM_onclick = function() {
    $c.lc.fn_PopFindExamIsu($c.stf.getObjectValue(cmb_SECUGRP_ID));
};
scwin.img_INVSTG_BILL_ACPT_DD_onclick = function() {
    popUpCalendar2(edt_INVSTG_BILL_ACPT_DD);
};
scwin.img_EXST_STRT_DD_onclick = function() {
    popUpCalendar2(edt_EXST_STRT_DD);
};
scwin.img_EXST_END_DD_onclick = function() {
    popUpCalendar2(edt_EXST_END_DD);
};
scwin.dts_Item_OnLoadError = function() {
    $c.stf.alert_error(dts_Item.text);
};
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    if (scwin.vBzProcsNo == "") {
        buttonSet.setInsertStatus();
        scwin.fn_initForm('C');
    } else {
        scwin.fn_initForm('U');
        buttonSet.setUpdateStatus();
    }
};
scwin.trs_Save_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    scwin.fn_read_sync();
    scwin.fn_parentRefresh();
    if (buttonSet.status == "U") {
        var parentWin = $c.frame.path("../");
        parentWin.dts_List.setFocusedCell(scwin.rowPos, 0);
    }
};
scwin.trs_Save_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_Save);
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Item);
    $c.elw.fn_searchCode();

    //fn_SetComboCode();
    var parentWin = $c.frame.path("../");
    scwin.vBzProcsNo = parentWin.clickBzProcsNo;
    scwin.mktTpCd = parentWin.scwin.mktTpCd;
    scwin.rowPos = parentWin.dts_List.getFocusedRowIndex();

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정

    if (scwin.vBzProcsNo != "") {
        scwin.fn_read_sync();
    } else {
        dts_Item.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=BENFCERT_PREEXAM_INOUT";
        dts_Item.reset();
        dts_Item.insertRow();
        $c.stf.setObjectValue(cmb_SECUGRP_ID, $c.stf.getObjectValue(parentWin.cmb_NEW_SECUGRP_ID));
        //alert( '[cmb_SECUGRP_ID]'+getObjectValue(cmb_SECUGRP_ID));
        scwin.fn_changeForm("02"); //초기값

    }

    //fn_initLabel(getObjectValue(cmb_SECUGRP_ID));

};
